--- /dev/null
+++ b/src/cost-labels.js
@@ -0,0 +1,9 @@
+// Cost labels per provider for the run summary.
+
+const CLI_FOR_PROVIDER = { 'claude-code': 'claude', 'codex-cli': 'codex', 'grok-cli': 'grok' };
+
+function costLabel(type, usd) {
+  return `${CLI_FOR_PROVIDER[type] || type}: $${usd.toFixed(2)}`;
+}
+
+module.exports = { costLabel };
